<script setup>
import { ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'

const petId = ref(0)
const petInfo = ref({})

// 测试详情数据
const petDetailMap = {
	1: {
		id: 1,
		name: '蛋挞',
		age: '1岁',
		breed: '威尔士彭布罗克柯基犬',
		avatar: 'https://picsum.photos/id/237/800/800',
		character: ['亲人', '爱晒太阳']
	},
	2: {
		id: 2,
		name: '布丁',
		age: '2岁',
		breed: '中华田园猫',
		avatar: 'https://picsum.photos/id/40/800/800',
		character: ['聪明', '安静']
	}
}

const tips = ref([
	'它腿脚偏短，日常尽量少让它频繁爬楼梯，保护关节；',
	'幼犬处于换牙期，可准备磨牙玩具，引导养成好习惯；',
	'性格温顺，适合独居人群、有小孩的家庭饲养。'
])

onLoad((options) => {
	petId.value = options.id || 1
	petInfo.value = petDetailMap[petId.value] || petDetailMap[1]
})

const goBack = () => {
	uni.navigateBack()
}

const applyAdopt = () => {
	uni.showModal({
		title: '申请领养',
		content: `确认申请领养${petInfo.value.name}吗？`,
		success: (res) => {
			if (res.confirm) {
				uni.showToast({ title: '申请已提交', icon: 'success' })
			}
		}
	})
}

const shareToFriend = () => {
	uni.showToast({ title: '分享功能', icon: 'none' })
}
</script>

